th_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李煴。", "biography": null, "status": "draft", "id": "1cdc1b9d-e9a6-55fd-b6ea-016b483c2f3d"}, {"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}]'::jsonb)
