INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张雄、冯弘铎据苏州，自号天成军", "start_year": 886, "end_year": 886, "time_original": "光启二年十月后条；具体日未载", "dynasty": "唐", "description": "张雄、冯弘铎因得罪时溥，率众渡江袭取苏州；张雄自称刺史，部众渐多，自号天成军。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b177f9d5-8a20-5eca-861e-b3beeb27b296"}, {"title": "诸葛爽去世，诸将立诸葛仲方为留后", "start_year": 886, "end_year": 886, "time_original": "光启二年十月后条；具体日未载", "dynasty": "唐", "description": "河阳节度使诸葛爽去世，刘经、张全义拥立其子诸葛仲方为留后。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2b587318-5dfd-53ec-8bad-d7242ed97d99"}, {"title": "李克修攻邢州不克而还", "start_year": 886, "end_year": 886, "time_original": "光启二年十月后条；具体日未载", "dynasty": "唐", "description": "李克修进攻邢州，未攻下而返回。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b37d877b-525d-5fa4-baaa-d5602454494a"}, {"title": "钱镠攻下越州，刘汉宏奔台州", "start_year": 886, "end_year": 886, "time_original": "光启二年十一月丙戌", "dynasty": "唐", "description": "钱镠攻下越州，刘汉宏逃往台州。", "phases": [], "location_name": "越州、台州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0515e288-c4a1-5619-af08-69f14c575191"}, {"title": "张骁举兵攻义成州城，安师儒杀夏侯晏、杜标", "start_year": 886, "end_year": 886, "time_original": "光启二年十一月条；具体日未载", "dynasty": "唐", "description": "安师儒把政事交给夏侯晏、杜标，军中不满；小校张骁聚众攻城，安师儒斩二人以平息军中怨气。", "phases": [], "location_name": "义成治所", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c2217b46-4e33-55da-8545-b6e64e8748d6"}, {"title": "朱瑄遣朱裕诱杀张骁", "start_year": 886, "end_year": 886, "time_original": "张骁举兵后；具体日未载", "dynasty": "唐", "description": "朱瑄意图取得滑州，遣朱裕诱杀张骁。", "phases": [], "location_name": "滑州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a646ed7a-c0f5-5bfb-a301-689b9398dd13"}, {"title": "朱全忠部攻下滑州并俘安师儒", "start_year": 886, "end_year": 886, "time_original": "光启二年十一月条；具体日未载", "dynasty": "唐", "description": "朱全忠先遣朱珍、李唐宾袭滑州，部队趁大雪一夜抵城，登城攻下，俘安师儒。朱全忠以胡真知义成留后。", "phases": [], "location_name": "滑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0b55b757-135f-5b40-ac0b-ba34c955b219"}, {"title": "田令孜到成都，请求寻医获准", "start_year": 886, "end_year": 886, "time_original": "光启二年十一月条；具体日未载", "dynasty": "唐", "description": "田令孜抵成都，请求寻医，获准。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "887a4d8c-bf8f-50a3-bfeb-b0a17d287c24"}, {"title": "诸军拔凤州，满存任防御使", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月戊寅", "dynasty": "唐", "description": "诸军攻下凤州，朝廷任满存为凤州防御使。", "phases": [], "location_name": "凤州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dba52208-5c2a-5749-8918-a8c1d7357966"}, {"title": "杨复恭传檄悬赏朱玫首级", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月戊寅之后", "dynasty": "唐", "description": "杨复恭向关中传檄，称取得朱玫首级者可授静难节度使。", "phases": [], "location_name": "关中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dbeb4054-c57b-5490-b284-ff989fe18b35"}, {"title": "王行瑜返京擒杀朱玫", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月甲寅", "dynasty": "唐", "description": "王行瑜多次战败后担心朱玫责罚，率军自凤州返京，于朱玫视事时将其擒斩，并杀其党。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "538e3f3a-c1eb-5b05-b27c-3f61c7251238"}, {"title": "朱玫被杀后长安诸军大乱焚掠", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月甲寅之后", "dynasty": "唐", "description": "朱玫被杀后诸军大乱，焚掠京城；《通鉴》记士民因失衣而冻死。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "981fde01-86c9-5350-adfe-25d04f54234b"}, {"title": "裴澈、郑昌图奉襄王煴奔河中", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月甲寅之后", "dynasty": "唐", "description": "裴澈、郑昌图率百官奉襄王煴逃往河中。", "phases": [], "location_name": "长安、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5761f731-916a-5fe8-b069-dcf69714f0e7"}, {"title": "王重荣诱捕并杀襄王煴", "start_year": 886, "end_year": 886, "time_original": "襄王煴抵河中后；具体日未载", "dynasty": "唐", "description": "王重荣佯作迎奉，捕获并杀襄王煴，囚裴澈、郑昌图；《通鉴》记随行百官死者近半。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9c6615bf-c4a4-5b12-a1b7-ce4b2627031a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

